globalThis.ANDE_CHUNKS["222828d907c527bf2fde5fd5bfaf2a87ac56e7e2f68061729295d1832b916ee3"] = [{"id":"kuaishou:10000","sourceKey":"kuaishou","company":"快手","title":"数据挖掘算法工程师","city":"北京","category":"数据科学","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10000","duty":"1、负责海量短视频生产链路算法优化，基于视频特效、用户画像、行为序列、消费反馈等大规模数据信号进行算法建模，加强特效、美颜等视频生产业务的智能化；\n2、通过异常检测、因果推断、自动归因等算法等对生产、消费数据进行挖掘，洞察业务痛点，指导业务优化方向；\n3、挖掘热点事件、预测流行趋势，帮助视频特效等业务更好运营和生产；\n4、挖掘用户特征，用于提升广告与用户匹配的效率、业务反欺诈、渠道反作弊、搜索索引等业务场景。","requirements":"1、计算机/数学/物理/信息等专业硕士及以上学历；\n2、扎实的统计学功底，擅长数据分析和科学实验方法，对机器学习、深度学习等主流算法理解深刻，且应用熟练；\n3、熟练掌握Python、C++、JAVA、R等至少一门编程语言，优秀的编码能力和习惯，良好的数据结构和算法功底；\n4、熟悉基于Hive、Spark、ElasticSearch、Mongodb等大数据平台的相关开发；\n5、热爱短视频行业，较强的沟通能力和逻辑表达能力，善于沟通和团队协作，具有较强责任心和目标导向意识。\n\n加分项：\n1、在KDD、NeurIPS、WWW、SIGIR、WSDM、ICML、IJCAI、AAAI、RecSys等顶会发表论文；\n2、在Kaggle等数据挖掘/机器学习竞赛获奖；\n3、在ACM等编程竞赛获奖。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10001","sourceKey":"kuaishou","company":"快手","title":"搜索算法工程师","city":"杭州","category":"搜索","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10001","duty":"1、参与综合短视频，直播，电商，本地，社交和多语言等搜索业务，用大规模机器学习，强化学习，多模态预训练等技术提升搜索质量，用户留存和点击率等核心业务指标；\n2、负责搜索query 意图分类，query 表征，query推荐，视频内容理解&多模态表征，多模态语义召回和相关性等搜索核心技术，提升搜索用户渗透率和相关性；\n3、负责搜索用户行为分析，语义和行为混合检索，多序列&多任务粗排，精排，重排等搜索排序技术，提升搜索质量和内容消费指标；\n4、负责搜索生态和机制，参与搜索混排，多目标优化，异构内容混排，短期和长期目标平衡，冷启动等搜索机制和算法。","requirements":"1、硕士及以上学历；\n2、熟悉自然语言处理、数据挖掘、机器学习等，有较强数据分析能力；\n3、熟练使用C/C++或Python。\n\n加分项：\n1、有搜索、推荐、广告、大数据等大型项目经验优先；\n2、国内和国际顶级会议发表论文的作者优先。\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10003","sourceKey":"kuaishou","company":"快手","title":"推荐大模型算法工程师","city":"北京","category":"推荐","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10003","duty":"1、探索大模型与推荐算法结合的下一代推荐系统技术，充分利用大模型的领域知识和学习范式为推荐系统注入新的能量，包括但不限于文本/ID生成式推荐、模型Scaling Law、用户超长序列端到端建模等；\n2、探索视频、文本和语音等多模态信号的高效处理方式以及与推荐系统对齐的能力，让推荐系统看懂、听懂和理解世界；\n3、混合专家、蒸馏剪枝等兼顾模型性能和效果的技术探索；\n4、紧跟行业及大模型技术发展，结合业界前沿技术和业务需求，打造大模型应用的最佳实践。","requirements":"1、硕士及以上学历，计算机、人工智能、统计学和数学相关专业；\n2、有较强的工程实现能力，熟悉C/C++、Python、 Java等至少一门主流编程语言；\n3、对搜广推算法、LLM(ChatGPT等)/多模态模型(LLaVa、BLIP2、instructBLIP等)模型或者量化/蒸馏/剪枝有深入研究经验；\n4、熟悉常用机器学习和数据挖掘算法，优秀的分析和解决问题的能力，同时具有较好的团队协作能力。\n\n加分项：\n1、密切关注业界最新进展，在国际顶会上发表过LLM/MLLM/推荐等相关论文；\n2、有搜广推业务上大规模机器学习优化落地经验；\n3、在ACM-ICPC/NOI/IOI编程竞赛或Kaggle等机器学习相关竞赛拿过奖项者优先。\n\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10004","sourceKey":"kuaishou","company":"快手","title":"推荐模型算法工程师 ","city":"北京","category":"推荐","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10004","duty":"1、参与业内最前沿的排序模型的迭代工作，通过优化模型精度提升用户体验；\n2、分析、理解用户数据和业务场景，设计适合业务发展的推荐算法和机器学习模型；\n3、迭代业内最前沿的推荐算法，并落地到快手最大的消费场景中。\n","requirements":"1、硕士及以上学历，人工智能、计算机、数学等相关专业；\n2、具备扎实的编码功底，能够熟练使用Python，Java，C++中的一种，有较强的工程实现能力；\n3、扎实的分析能力，能熟练使用SQL，Jupyter，Spark进行数据分析；\n4、熟悉机器学习模型，有大规模实时模型开发、迭代经验，如Wide and Deep,DCN,deepFM,Transformer,SIM等模型技术；\n5、热爱技术，勇于实践新技术与新想法；用于探索技术领域，并持续迭代拿到线上效果。\n\n加分项：\n1、有推荐系统召回、排序，在线广告，搜索引擎，自然语言，计算机视觉等相关领域经验者优先；\n2、在SIGKDD、ICML、NIPS、WSDM、WWW、ACL、RECSYS等相关国际顶级会议上有文献发表；\n3、有ACM/Topcoder Algorithm或类似算法竞赛经历者优先。\n\n","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10005","sourceKey":"kuaishou","company":"快手","title":"推荐算法工程师","city":"北京","category":"推荐","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10005","duty":"1、参与亿级用户规模的视频推荐优化，提升停留时长、点击率、留存率等核心指标；\n2、参与机器学习、深度学习领域的技术研发工作，包括但不限于深度模型设计与优化、强化学习、迁移学习、图神经网络等的算法和系统研发等；\n3、分析海量用户行为数据和视频数据，增加有效的特征，挖掘用户兴趣，优化排序机制；\n4、通过超大规模机器学习模型和系统，使用先进的检索和排序手段，优化社区生态，优化快手短视频推荐效果；\n5、针对海量用户行为数据，提供分布式的算法实现的解决方案，大幅提升算法计算规模和性能；\n6、参与搭建推荐系统框架，提供高并发，大数据，高效可靠的线上服务；\n7、参与全域流量博弈的机制设计，协助拓展业务边界；\n8、参与前沿问题探索与研究，结合实际应用场景，提供全面的技术解决方案。","requirements":"1、硕士及以上学历，计算机、数学或统计学相关专业；\n2、熟悉Linux、C++、Java或Python，优秀的编码能力，扎实的数据结构和算法功底；\n3、具有推荐系统、机器学习、数据挖掘或者自然语言理解等相关领域知识；\n4、善于阅读文献，快速学习，具备优秀的分析和解决问题的能力，良好的沟通协作能力。\n\n加分项：\n1、有推荐系统、机器学习、信息检索、自然语言理解、计算广告学及算法博弈论相关领域研究或实习经验；\n2、有实际线上的高并发架构开发和调优的经验；\n3、在SIGKDD、ICML、NIPS、WSDM、WWW、ACL、RECSYS等相关国际顶级会议上有文献发表；\n4、有ICPC、Topcoder Algorithm或类似算法竞赛经历者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10006","sourceKey":"kuaishou","company":"快手","title":"推荐系统工程师","city":"北京","category":"推荐","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10006","duty":"1、参与设计与建设个性化推荐系统的策略与模型引擎，提升系统性能和稳定性；\n2、参与设计与建设个性化推荐系统的画像和索引存储系统，利用最新存储硬件SSD和NVM来升级加速；\n3、参与推荐机器学习平台生态工具的开发，例如训练平台、预估平台等，并利用GPU、FPGA等硬件进行异构加速；\n4、优化算法可扩展性，优化推荐系统迭代的通用平台，保障算法策略模块快速迭代。","requirements":"1、本科及以上学历；\n2、熟练掌握服务性能分析与优化相关技能；\n3、掌握主流开发语言如C++/Java/Python中的一种或多种，有较强的工程实现能力，有良好的代码风格。\n\n加分项：\n1、有大规模数据处理及服务经验；\n2、有互联网公司推荐、广告或搜索相关场景下实习经历，或者有优秀开源项目贡献；\n3、有OI、ICPC等竞赛优秀成绩；\n4、曾发表过系统领域相关国际顶会论文。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10008","sourceKey":"kuaishou","company":"快手","title":"网络传输算法工程师","city":"北京","category":"网络传输","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10008","duty":"1、负责快手直播、实时音视频交互、短视频传输协议和算法的设计与优化；\n2、负责快手音视频体验的优化，包括直播推流/拉流、点播消费、作品发布、QoE建模等；\n3、优化各种基础网络下(WiFi、3G、4G、5G等)的传输性能，包括带宽利用率、延迟、成功率等；\n4、预研强化学习/深度学习/在线学习等在网络传输优化领域的落地与应用，跟踪国内外最新技术与标准。","requirements":"1、硕士及以上学历，计算机、通信等相关专业，熟悉C/C++语言；\n2、熟悉常见基础网络特性，熟悉网络编程，计算机网络等知识；\n3、深入理解强化学习/深度学习，熟悉常见模型与平台；\n4、要求有较强的沟通表达能力和团队意识。\n    \n加分项：\n1、对带宽预测、拥塞控制算法、基于UDP的协议优化等有深入理解者优先；\n2、有强化学习类项目实践经验者优先；\n3、有NOI、ACM、TopCoder等相关竞赛经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10012","sourceKey":"kuaishou","company":"快手","title":"音频/音乐AIGC算法工程师","city":"北京","category":"音频处理","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10012","duty":"1、负责AI音频/音乐生成大模型关键算法研发和优化，包含但不局限于T2A、V2A和AI歌曲生成等方向；\n2、负责跟进行业前沿技术发展趋势，跟踪国际最新技术发展方向；\n3、推动音频/音乐AIGC技术在快手各业务场景中的落地，探索音频/音乐生成技术在业务中的新玩法和业务创新。","requirements":"1、硕士及以上学历，机器学习、模式识别、信号处理等计算机相关专业优先；\n2、有较丰富的语音/音频/音乐生成大模型相关领域经验；\n3、熟练掌握C/C++、Python，有较强的代码实现能力；\n4、具有独立解决问题的能力，良好的表达能力、沟通能力和团队合作意识。\n\n加分项：\n1、有T2A、V2A、TTS和音乐生成大模型技术研发经验者优先；\n2、相关顶会或期刊上发表论文者优先（ICASSP，Interspeech，ISMIR，ICML，AAAI，NIPS等）。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10016","sourceKey":"kuaishou","company":"快手","title":"大模型应用算法工程师","city":"北京","category":"自然语言处理","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10016","duty":"1、负责通过基于大语言模型及多模态大模型的微调、prompts调优、指令构建及演化技术，将大模型的生成、理解、交互能力在公司核心业务场景应用落地，包括但不限于AIGC创意生成、视频处理、智能化特效、智能对话、代码生成、音视频传输、电商场景内容理解等；\n2、负责LLM及多模态大模型的应用中台及相关技术模块搭建，包括但不限于Agents 、RAG、 function call、system prompts等，探索大模型应用前沿及新兴应用场景； \n3、跟踪行业及大模型技术发展，结合业界前沿技术和业务需求，打造大模型应用的最佳实践；\n4、了解业务，与公司各技术团队密切配合，能与产品、运营等角色高效沟通需求和目标，发挥自己的主观能动性，设计技术解决方案，培养自己的良好的业务sense和综合素质。","requirements":"1、硕士及以上学历，计算机、人工智能、数学相关专业；\n2、有较强的工程实现能力，熟悉LLM及MLLM基本原理、大模型微调/RLHF等技术，熟悉C/C++、Python、Java等至少一门主流编程语言；\n3、对计算机视觉、自然语言处理、多模态、知识图谱、机器学习等相关领域有深入的理解，且有相关实际项目经验；\n4、对学术前沿有浓厚兴趣，时刻跟进技术前沿，并善于利用各类技术解决复杂的实际问题，有良好的沟通表达能力。\n\n加分项：\n1、有LLM/M-LLM、AIGC、3D模型、智能对话、知识图谱、观点情况分析等项目落地应用经验者优先；\n2、在计算机视觉、自然语言处理、多模态、机器学习等相关领域有顶级学术论文发表优先；\n3、在ACM-ICPC/NOI/IOI编程竞赛或机器学习相关竞赛拿过奖项者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10022","sourceKey":"kuaishou","company":"快手","title":"游戏3D角色设计师","city":"杭州","category":"游戏类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10022","duty":"1、负责游戏中3D角色与相应道具、武器的制作及输出工作；\n2、精确还原原画设计并丰富角色的细节；\n3、根据项目制作规范，检查审核资源，确保符合项目的生产需求。","requirements":"1、本科及以上学历；\n2、具有扎实的美术功底，热爱游戏美术，具备优秀的审美能力；\n3、能掌握常用3D制作软件，了解游戏美术的制作流程和规范；\n4、具有很强的学习能力和毅力，能吃苦耐劳，对自己的专业水平有严格的要求和追求；\n5、较强的文字理解力和表达能力，思维灵活，性格开朗，善于沟通与合作；\n6、投递简历时，请附带个人作品集或个人作品链接地址。\n\n*投递简历时，请在简历中标注游戏经历 （游戏名，游戏总时长，游戏段位及成就）。\n*作品集要求：\n1、请务必在标准简历里的“作品信息\"或”其他附件“处，上传包括但不限于与本岗位相关的作品集；\n2、相关文件大小需控制在100mb内，鼓励以压缩包的形式上传；\n3、不建议以网盘链接形式上传，若以网盘链接的形式上传作品，请不要设置提取码。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10044","sourceKey":"kuaishou","company":"快手","title":"多模态模型优化算法工程师 ","city":"上海/北京","category":"计算机视觉","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10044","duty":"1、diffusion步数压缩：探索diffusion模型的one-step / few-steps的无损蒸馏算法，跟进学术界最前沿的few-steps diffusion算法，包括但不限于consistency modeling、shortcut、score distillation等方案，打造实时化的极致高效可灵/可图大模型；\n2、高效attention设计：探索新一代注意力实现机制，包括但不限于sparse/quant-attention、linear-attention、mamba等，打破attention计算平方复杂度限制，解决长序列视频/图像引起的推理挑战，推进可灵/可图大模型的长序列场景下的推理极限；\n3、强化反馈优化：应用DPO/GRPO/PPO等强化学习的手段调优模型效果，在模型压缩的前置条件下探索强化学习与压缩算法的化学反应，推动可灵/可图大模型的效果-效率帕雷托前沿新","requirements":"1、硕士及以上学历，数学、计算机、自动化、电子等专业优先；\n2、熟练掌握diffusion原理，具备公式推理和证明的能力，有过相关的研究经历和实践经验者优化；\n3、熟悉transformer结构及其变种，熟悉attention的设计和多种变种实现，掌握triton；\n4、熟练掌握线性线数、概率论、信息论、凸优化等基础知识；了解矩阵论、随机过程等；\n5、有较强的自驱力和学习力，对生成式模型有强烈的兴趣。\n\n加分项：\n1、有NIPS/ICLR/ICML/CVPR等顶会发表经历者优先；\n2、有强化学习的实践经历优化。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10045","sourceKey":"kuaishou","company":"快手","title":"【快Star】多模态理解工程师-视觉生成","city":"深圳/北京","category":"计算机视觉","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10045","duty":"深度优化多模态大模型的Caption、表征、改写能力，打造业界第一梯队的多模态大模型，在AIGC技术指标上超过GPT-4o、Gemini Pro等闭源模型，落地于快手各业务线。","requirements":"1、硕士及以上学历，有LLM和VLM大模型训练经验；有较强的代码动手开发能力，对多模态大模型基座能力提升有较高的热情；\n2、良好的沟通协作能力，能够与团队紧密合作，共同推进项目进展。\n\n加分项：\n1、在ACM/ICPC、Top Coder、Kaggle等比赛中取得过良好成绩是加分项；\n2、在大模型领域，发表过相关论文是加分项；\n3、多模态大模型的项目经历和实习经历是加分项。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10060","sourceKey":"kuaishou","company":"快手","title":"多模态理解工程师-视觉生成","city":"北京","category":"计算机视觉","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10060","duty":"深度优化多模态大模型的Caption、表征、改写能力，打造业界第一梯队的多模态大模型，在AIGC技术指标上超过GPT-4o、Gemini Pro等闭源模型，落地于快手各业务线。","requirements":"1、硕士及以上学历，有LLM和VLM大模型训练经验；有较强的代码动手开发能力，对多模态大模型基座能力提升有较高的热情；\n2、良好的沟通协作能力，能够与团队紧密合作，共同推进项目进展。\n\n加分项：\n1、在ACM/ICPC、Top Coder、Kaggle等比赛中取得过良好成绩是加分项；\n2、在大模型领域，发表过相关论文是加分项；\n3、多模态大模型的项目经历和实习经历是加分项。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10062","sourceKey":"kuaishou","company":"快手","title":"AI应用服务端开发工程师","city":"北京","category":"服务端","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10062","duty":"1、负责AI工程化落地，利用提示词工程，微调等一系列技术，解决将大模型用于生产场景的一系列复杂问题，平衡效果，成本，速度；\n2、开发适用于生产场景的Agent系统，探索Agent提示词工程的最佳实践，解决将Agent应用于产品时遇到的最棘手的挑战；","requirements":"1、本科及以上学历，具备扎实的计算机专业基础，比如操作系统、计算机体系结构等；\n2、熟练掌握C/C++/Java/python，具备优秀的编程素养，对代码质量追求极致；\n3、思维严谨，逻辑清晰，有强烈的技术热情，工作责任感强；\n4、日常熟练使用各种AI工具，对大模型的工作原理有一定了解；\n5、了解提示词工程，有Agent系统开发经验的优先；","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10097","sourceKey":"kuaishou","company":"快手","title":"游戏AI算法工程师-LLM","city":"杭州","category":"自然语言处理","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10097","duty":"1. 负责剧情剧本生成&对话NPC&智能agent等相关算法的开发和研究，包含但不限于LLM模型的训练（continue train/SFT/强化训练等），闭源LLM模型的使用，MCP，RAG，多agent协作等能力的开发；\n2. 负责将相关算法模型进行部署和优化，并完成与相关需求部门的接口对接；\n3. 负责游戏环境中相关AI需求发掘，设计，技术研发，以及推动上线落地和不断迭代优化；\n4. 关注AIGC业界动态，关注AI与游戏结合的新方向，引入前沿的技术和方法，参与团队基础研究能力；","requirements":"1. 计算机、统计、人工智能相关专业硕士及以上学历；\n2. 熟悉常见的AIGC类算法（LLM/MLLM/RAG/MCP等），follow较新的算法实现，熟练掌握常用的深度学习网络以及其训练、优化的方法；\n3. 扎实的数学基础，有统计学、模式识别、矩阵计算和最优化方法的理论基础；\n4. 熟悉TensorFlow/Pytorch等主流的深度学习框架之一，熟练使用C++/Python等至少一种编程语言，熟悉Linux开发环境；\n5. 工作细致、思想敏锐，具有发现、归纳问题的能力、逻辑分析能力及沟通能力；\n6. 热爱游戏行业，对于常见游戏涉及的AI技术有接触，对于对话机器人/剧情剧本生成/智能NPC等与AI方向有相关研究的优先；\n7. 国际顶尖会议或期刊发表过相关论文或得到过国际比赛名次的优先；\n\n*投递简历时，请在简历中标注游戏经历 （游戏名，游戏总时长，游戏段位及成就）。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10467","sourceKey":"kuaishou","company":"快手","title":"风险策略分析师-月付方向","city":"杭州","category":"服务端","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10467","duty":"1、利用公司内部数据资源，深度分析用户行为数据与属性，挖掘潜在价值；\n2、全面理解信贷产品的特性、应用场景和目标用户，精准识别风险点；\n3、综合客户在贷前、贷中、贷后的行为数据，以及内外部多维数据，进行信用风险与欺诈风险的评估和量化；\n4、基于客户风险量化结果，制定准入规则、授信额度、定价策略、还款模式及清退方案，实现业务目标的最优解；\n5、设计科学合理的测试方案，提供数据支持并优化策略调整，助力业务规划。","requirements":"1、本科及以上学历，数学、统计学等相关专业优先；\n2、学习能力强，能迅速掌握工作所需技能，适应高强度和快节奏的工作环境；\n3、熟悉常见统计方法，熟练操作SQL、Python等数据分析和建模工具。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10473","sourceKey":"kuaishou","company":"快手","title":"【快Star】基础大模型算法工程师—强化学习方向","city":"北京","category":"机器学习","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10473","duty":"1、深入研究强化学习在快手自研语言大模型、多模态大模型、推荐大模型中的创新应用，提升大模型能力上限；\n2、负责大模型的基础技术研究，包括但不限于训练算法、框架及模型架构相关的基础技术探索和创新；\n3、在顶级会议与开源社区塑造快手大模型团队的技术影响力。","requirements":"1、硕士及以上学历，强化学习相关专业优先；\n2、在大规模预训练、模型对齐、强化学习、RAG、Agent等至少一个方向有深厚的项目经验和洞察力；\n3、动手能力强，编程能力强；\n加分项：\n1、在AI领域的国际顶级会议或者期刊上作为核心贡献者有丰富的学术成果；\n2、在开源社区发布有一定影响力的项目。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10559","sourceKey":"kuaishou","company":"快手","title":"海外数据分析师","city":"北京","category":"战略分析类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10559","duty":"1、基于数据分析、量化建模、市场调研等工具对产品和市场进行理解和刻画，解决短视频、直播及新产品增长相关的各种复杂商业分析问题，能独立完成从方案设计、数据加工与分析，到结论展示的整个流程；\n2、对公司内外部数据进行挖掘，在深入的产品理解与用户洞察基础上，自主发掘课题，提出有实效的建议，驱动产品迭代；\n3、针对不同业务：市场、产品、增长等业务线做数据支持。","requirements":"1、本科及以上学历，英文流畅；\n2、具有一定概率统计基础，具有数据建模、数据挖掘经验者优先；\n3、熟练使用SQL、Python或者R，对数据进行处理、分析和可视化呈现；\n4、了解常用的机器学习算法；\n5、很强的逻辑思维、产品理解和商业洞察力，能以合适分析框架解决各种复杂问题，批判性思考；\n6、对欧美流行文化、PGC/UGC视频、直播、综艺、音乐、电影等有兴趣及一定认知者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10685","sourceKey":"kuaishou","company":"快手","title":"销售运营-分析方向","city":"北京","category":"销售类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10685","duty":"1、构建全面的、准确的、能反映电商及商业化业务特征的宏观、微观指标体系，并基于业务监控指标体系，及时发现与定位业务问题；\n2、理解商业本质和业务逻辑，对不同行业的电商玩法有深入研究，根据业务发展需要，输出特定专题分析，提供及时有效的分析结果和策略方案，并寻找合理的业务新增长点；\n3、关注竞对信息及行业发展变化，及时做出相应的策略响应。","requirements":"1、理工科、统计学、数学、计算机、信息工程等专业优先、本科及以上学历；\n2、具备良好的逻辑思维能力、跨部门沟通协作能力，学习能力强，可快速理解并把握业务需求，善于发现问题解决问题，可以解决各种复杂问题；\n3、熟练使用SQL、Python对数据进行处理、分析和可视化呈现，能高效地与数据技术团队进行沟通。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10702","sourceKey":"kuaishou","company":"快手","title":"策略产品培训生","city":"北京","category":"策略产品","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10702","duty":"【加入我们，你将做什么？】\n1. 策略设计与优化：参与公司核心业务（如直播、消费、搜索、生产社交、增长、房聘等）的策略产品设计，协同技术团队推动策略落地，持续监控效果并迭代优化，推动业务价值的提升；\n2. 数据驱动决策：基于AB实验、用户行为数据等，量化评估策略的成本、影响和收益，输出可落地的改进建议；构建业务数据监控体系，快速定位问题并推动解决；\n3. 跨团队协同落地：在复杂的业务场景中，与业务、运营、技术等多方团队紧密配合，横向协同多方团队，以全局视角推动推动策略在全链路的实施和落地；\n4. 行业洞察与创新： 跟踪互联网行业趋势和前沿技术，探索创新策略方向，通过用户调研、竞品分析、数据分析，主动学习和了解业界最新动态，发现产品机会点。\n\n【加入我们，你能获得什么？】\n从算法、策略产品、商业多重角度，学习并建立产品机制；\n直面业务挑战，全方位学习优秀策略产品经理的核心能力；\n在资深导师的","requirements":"1. 本科及以上学历，工学/理学以及工程相关的专业优先，有计算机相关竞赛经历优先；\n2. 扎实的分析基础或代码能力，擅长使用各种工具进行数据分析，熟练掌握熟练使用SQL、Python或R进行数据提取和分析，并能基于数据洞察持续优化策略设计；\n3. 互联网产品重度使用者，有互联网策略产品/技术/分析等相关实习经验优先，对用户需求和商业逻辑敏感，逻辑清晰，具备结构化思考和系统性解决问题的能力，能独立输出产品方案；\n4. 良好的跨界协同、沟通表达、项目管理能力，能协调多方资源推动目标达成；\n5. 较强的自驱力和抗压力，对业务未知领域持续保持好奇与探索，适应互联网快速迭代的环境。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10770","sourceKey":"kuaishou","company":"快手","title":"HR-薪酬福利类","city":"北京","category":"职能类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10770","duty":"加入快手CB团队，你可以：\n参与行业领先的薪酬福利设计，深度参与快手薪酬体系的建设，打造具有市场竞争力的激励机制；\n成为数据驱动的决策者：通过薪酬数据分析与调研，提升数据洞察力，助力公司战略落地；\n快速成长为薪酬福利专家：在快手高速发展的环境中，积累丰富的薪酬福利管理经验，助力个人职业发展。\n1、参与公司薪酬福利绩效体系的构建与优化，根据公司业务与行业特性，制定公司薪酬福利绩效的政策与制度；协同支持薪酬调整、激励方案、绩效股权、薪酬政策、福利设计与优化等项目；\n2、进行成本数据分析与方案推进，进行人工成本管理模式对标研究，通过人工成本预算管理模型，支持业务成本管理落地，最终推进公司成本项目管理及落地。\n3、参与薪酬福利绩效相关分析报告制作，根据公司组织架构与业务发展规划，参与制定人力资源年度人力编制与成本规划；\n4、协同支持公司级薪酬福利绩效重点项目，独立完成项目模块中的工作内容，深入思考","requirements":"1、本科及以上学历，财务管理、金融会计、人力资源、统计、经济学等相关专业；\n2、有数据敏感度，具备一定的数据分析能力优先；\n3、逻辑清晰，理解准确，表达有条理；责任心强，耐心细致，具有钻研精神，熟练运用Excel、Word等办公软件；具备较好的协作精神；\n4、有互联网实习或咨询公司项目实习经验的优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10771","sourceKey":"kuaishou","company":"快手","title":"HR-组织战略分析师","city":"北京","category":"职能类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10771","duty":"加入组织发展团队你可以：\n1、拥有与 HR 各职能、技术、分析、产品等多个领域团队深度合作的机会，快速成长为具备复合能力的综合性人才；\n2、获得实际参与公司级重点管理项目、发起人力资源领先实践的机会；\n3、获得来自mentor和组织的充分的授权和信任；\n4、与拥有知名高校背景、来自头部互联网/咨询公司同事合作的机会。\n\n职位描述：\n1、围绕 AI 组织转型、人才策略等话题，提供解决方案并推动落地、拿到结果；\n2、通过数据分析、行业调研为企业的组织发展和人才管理定义重要问题，并提出相应的工作策略；\n3、参与公司级组织与人才项目，与COE、HRBP、数据分析、企业应用系统等团队合作，推动项目落地。","requirements":"1、经验不限，欢迎产品技术运营等背景的同学投递；\n2、希望你拥有结构化思维、有好奇心，独立思考、喜欢追问为什么，学习成长是你的重要驱动力。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10773","sourceKey":"kuaishou","company":"快手","title":"HR-BP类","city":"北京","category":"职能类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10773","duty":"加入快手HRBP团队，你可以：\n成为业务团队的战略合作伙伴，深度参与公司核心业务发展；\n在复杂多变的业务场景中锻炼全局视角和解决问题的能力；\n快速成长为具备战略思维的HR专家，助力组织与个人共同成功。\n1. 业务伙伴支持：贴近业务一线，深入了解业务战略与组织现状，提供定制化的人力资源解决方案，助力业务目标达成；\n2. 组织诊断与优化：通过组织健康度调研、人才盘点等方式，发现并解决组织问题，推动组织效能提升；\n3. 重点项目落地：推动公司级人力资源重点项目（如绩效管理、人才发展、文化建设等）在所支持业务单元的实施，并对效果进行反馈与优化；\n4. 团队建设与员工关怀：帮助管理者提升团队凝聚力，推动新员工融入、团队建设和员工关怀等工作；\n5. 数据驱动决策：通过数据分析（如离职率、绩效分布等），为业务部门提供量化的决策支持。","requirements":"1. 本科及以上学历，人力资源管理、心理学、工商管理等相关专业优先；\n2. 具备目标导向和自我驱动能力，能够从业务视角出发解决人力资源问题；\n3. 拥有优秀的沟通表达能力和团队协作意识，能够高效推动跨部门合作；\n4. 熟练使用数据分析工具，能够通过数据驱动优化方案。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10774","sourceKey":"kuaishou","company":"快手","title":"HR-招聘类","city":"北京","category":"职能类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10774","duty":"加入快手招聘团队，你可以：\n把控公司人才入水口，为公司快速发展打好人才基础；\n有机会与行业顶尖人才对话，深入理解互联网行业的业务逻辑；\n全流程参与招聘策略制定与实施，快速成长为招聘领域的专家。\n1. 招聘策略制定：基于公司核心业务战略，深入洞察业务需求，制定并执行高效的招聘策略，确保关键岗位人才供给；\n2. 全流程招聘管理：负责招聘全流程，包括需求分析、渠道拓展、候选人评估、Offer谈判及入职跟进，提升招聘效率与候选人体验；\n3. 数据驱动招聘优化：分析招聘漏斗数据（如转化率、招聘周期等），通过数据监控与分析持续优化招聘流程与工具；\n4. 市场与人才洞察：收集并分析行业人才动态，搭建人才地图，输出前瞻性的人才规划与招聘策略；\n5. 创新招聘模式：探索并实践新兴招聘方式（如AI招聘、社交媒体招聘、人才社区运营等），提升招聘效果与雇主品牌影响力。","requirements":"1. 本科及以上学历，不限专业，具备招聘或互联网行业相关实习经验者优先；\n2. 具备优秀的学习能力、逻辑思维能力和反思能力，能够深入理解业务需求并快速响应；\n3. 拥有强烈的责任心和韧劲，能够长期坚持解决复杂问题并推动落地；\n4. 具备良好的人际感知力和项目管理能力，能够与内外部优秀人才对话，深入理解互联网行业；\n5. 熟悉招聘管理系统（如Workday、Taleo等）或具备相关经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10775","sourceKey":"kuaishou","company":"快手","title":"HR-流程与运营类","city":"北京","category":"职能类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10775","duty":"加入快手SSC，你可以：\n深度参与HR数字化转型，积累前沿的流程管理与系统实施经验；\n在高效协作的团队中快速提升项目管理与跨部门沟通能力；\n成为推动HR运营效率提升的核心力量，为组织赋能。\n1. 人力运营管理：参与员工全生命周期的运营管理，包括劳动关系管理、员工入离职流程优化、政策合规管理等；\n2. 制度与流程优化：完善人力运营相关制度与流程，如员工关系管理、风险合规审计、户政资源管理等，提升运营效率；\n3. 用户体验提升：通过HR用户体验项目（如体验场域、用户洞察等），优化员工体验并提升用户满意度；\n4. 数字化与系统化建设：推动人力运营工作的信息化与系统化，参与HR系统需求分析、设计与实施；\n5. 跨部门协作：协调各部门资源，确保决策在各部门间快速传递并高效执行，搭建内部高效沟通渠道；\n6. 政策支持与咨询：为员工和HRBP提供专业政策与规则的解答，支持日常运营工作。","requirements":"1. 本科及以上学历，对人力运营工作充满热情；\n2. 具备良好的沟通能力、逻辑思维能力和学习能力，能够在高压环境中高效完成任务；\n3. 熟悉HR信息系统（如SAP SuccessFactors、Oracle HCM等）或具备相关经验者优先；\n4. 性格积极，做事踏实务实，具备较强的自驱力和团队合作意识。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10814","sourceKey":"kuaishou","company":"快手","title":"云原生大数据调度工程师","city":"北京/杭州","category":"服务端","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10814","duty":"1、参与快手大数据Spark、Flink、MR等作业的编排调度工作；\n2、基于Kubernetes等云原生技术完善资源统一调度、服务的多集群联邦编排，提升资源及服务变更效率； \n3、参与公司在离线混部系列机制的设计与开发，提升集群异构资源的使用效率； \n4、探索容器领域前沿技术，参与容器云全局技术优化与落地实践。","requirements":"1、本科及以上学历，计算机相关专业；\n2、掌握常用的数据结构/算法，扎实的代码功底与良好的编码习惯；\n3、熟悉Golang、Java等开发语言中至少一种，Golang优先；\n4、具有Docker、Kubernetes、Istio、Flink、Spark、Yarn等使用或二次开发经验者优先，有开源参与经历者优先；\n5、善于主动思考和行动，乐于解决具有挑战性的问题，对待技术有强烈兴趣者优先；\n6、有互联网基础平台相关方向实习经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10844","sourceKey":"kuaishou","company":"快手","title":"用户运营-用户服务方向","city":"北京","category":"用户运营","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10844","duty":"1. 深入了解用户服务业务，初期通过深度实践体验与培训，深入理解业务流程和用户需求；\n2. 流程优化：通过项目管理，善于发现流程中存在的问题并及时提供优化建议，设计改进方案并推动落地；\n3. 团队赋能：协助管理客服团队，监控项目进度与质量，提高团队日常工作效率；\n4. 业务探索：积极参与并协助智能客服相关AI场景的应用与实践，对前沿领域有热情。","requirements":"1. 本科及以上学历，专业不限，对互联网用户服务业务感兴趣；\n2. 沟通和文字表达能力强，逻辑清晰，乐于&善于深度思考钻研问题，具备快速学习和迭代的能力；\n3. 拥有互联网服务运营、用户运营等相关实习经验优先，具备团队协作精神；\n4. 积极乐观，具有较好的抗压性和责任感，有同理心，乐于&善于发挥正面精神影响他人。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10926","sourceKey":"kuaishou","company":"快手","title":"AI IaaS计算引擎研发工程师","city":"杭州/北京","category":"系统架构","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10926","duty":"1、承担AI时代IaaS层计算引擎的设计和研发工作，致力于构筑行业领先的AI云计算基础底座；\n2、重点负责快手内部大模型训练与推理场景的优化工作，通过构建全面的异常发现与故障自愈机制、提升模型加载时效、实施GPU池化等措施，提升平台的MFU（资源利用率）和MTTR（故障恢复时间）等核心指标；\n3、基于云原生系列技术，跟进AI链路中各核心组件的研发工作，包括训练推理服务编排、GPU资源调度和混布，以及高性能存储、高性能RDMA网络等的对接支撑；\n4、参与构建异构多芯计算集群，持续优化GPU资源调度、GPU虚拟化、在离线推理隔离、快照等核心能力，有效提升多芯供应能力和集群资源效率。","requirements":"1、本科及以上学历，计算机相关专业；\n2、熟悉常用数据结构与算法，精通计算机基础，具备扎实的编程基础和良好的编码习惯；\n3、有优良的逻辑分析能力和算法基础，熟练掌握至少一种编程语言（如 Python、Golang、Java、C 等）；\n4、具有以下任一技能要求者优先：\na. 熟悉Megatron-LM、DeepSpeed、FairScale、TensorRT-LM等大模型技术中的一种；\nb. 熟悉vLLM、LMCache、KVCache多级缓存卸载等技术；\nc. 熟悉CUDA、GPU底层硬件技术；\nd. 熟悉Alluxio、Lustre等高性能存储技术；\ne. 有高性能计算背景和参与过相关开源项目优先；\n5、有AI推理/训练研究型经验者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10965","sourceKey":"kuaishou","company":"快手","title":"多模态Data Infra开发工程师","city":"北京","category":"系统架构","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10965","duty":"1、对接视频/图片/音频等各类多模态模型的数据生产需求，打造业界领先的多模态数据生产引擎，持续提升训练数据的规模、质量和迭代效率，支撑可灵全系多模态生成模型训练；\n2、搭建 Data Centric的多模态数据处理pipeline，包括数据处理算子开发、跨模态检索引擎开发、多模态数据的内容理解、质量筛选、组织与合成等关键环节；\n3、构建高可用、高吞吐的数据算法服务框架，支持多模态模型服务的快速部署，持续优化多模态数据的存储以及检索效率。","requirements":"1、本科及以上学历，计算机、软件工程、人工智能等相关专业优先；\n2、计算机基础扎实，熟练掌握Java/C++/Python语言中的一种，有服务端系统的开发经验；\n3、聪明好学，有较强的自驱力和学习力，良好的沟通协作能力；\n4、熟悉分布式计算或大数据处理框架（如Ray、Flink、ES等），或者大模型推理训练框架（如vLLM、SGLang、PyTorch）者优先。","description":"","jdComplete":false,"sourceStatus":null},{"id":"kuaishou:10991","sourceKey":"kuaishou","company":"快手","title":"数据科学家","city":"北京","category":"战略分析类","channels":[],"employment":"full-time","talentPlan":null,"date":null,"dateKind":null,"url":"https://campus.kuaishou.cn/recruit/campus/e/#/campus/job-info/10991","duty":"【加入我们，你将做什么？】\n1. 基于数据分析、量化建模、市场调研等工具对产品和市场进行理解和刻画，解决短视频、直播及新产品增长相关的各种复杂商业分析问题，能独立完成从方案设计、数据加工与分析，到结论展示的整个流程；\n2. 对公司内外部数据进行挖掘，在深入的产品理解与用户洞察基础上，自主发掘课题，提出有实效的建议，驱动产品迭代；\n3. 针对不同业务：市场、产品、增长等业务线做数据支持。\n\n【加入我们，你能获得什么？】\n1. “牛人”导师团零距离带教\n实战派领航员：由多位数据分析负责人担任主导师团，人均操盘过亿级数据的拆解；\n1v1成长伙伴：同时配备资深导师全程带教，从需求拆解到方案落地，手把手带你入门并逐步突破认知的盲区；\n咖啡基金：配备咖啡基金，可用于定期与导师的「咖啡角」讨论会；\n2. 快手流量生态全景认知\n深度解析流量体系：深度理解公司业务，参与进核心业务的数据拆解分析；\n真实战场带","requirements":"1. 本科及以上学历，工学/理学以及工程相关的专业优先，有数据相关竞赛经历优先；\n2. 扎实的分析基础或代码能力，擅长使用各种工具进行数据分析，熟练掌握熟练使用SQL、Python或R进行数据提取和分析，并能基于数据洞察持续反哺业务；\n3. 互联网产品重度使用者，有互联网策略产品/数据分析等相关实习经验优先，对用户需求和商业逻辑敏感，逻辑清晰，具备结构化思考和系统性解决问题的能力，能独立输出产品方案；\n4. 良好的跨界协同、沟通表达、项目管理能力，能协调多方资源推动目标达成；\n5. 较强的自驱力和抗压力，对业务未知领域持续保持好奇与探索，适应互联网快速迭代的环境。\n\n【我们寻找这样的你】\n1. 痴迷用数据和逻辑破解复杂问题，对用户行为背后的规律充满好奇；\n2. 渴望在万亿级流量战场上操盘核心策略，同时对能够拥有硬核的分析能力，有强烈诉求；\n3. 期待与顶尖人才并肩作战，乐于沟通协调资源，三","description":"","jdComplete":false,"sourceStatus":null}];
